    addpoints(h, x, sin(x));
    drawnow limitrate
end

h = animatedline(Marker="o");
for k = 1:50
    addpoints(h, k, randn);
    drawnow
end
[xd, yd] = getpoints(h);

for k = 1:30
    plot(cos((1:100)/8 + k/4)); ylim([-1 1]); drawnow
    [A, map] = rgb2ind(frame2im(getframe(gcf)), 256);
    if k == 1
        imwrite(A, map, "anim.gif", LoopCount=Inf, DelayTime=0.05);
    else
        imwrite(A, map, "anim.gif", WriteMode="append", DelayTime=0.05);
    end
end

